create table if not exists public.player_market_values (
  rank             integer,
  player_name      varchar,
  position         varchar,
  age              integer,
  nationality      varchar,
  club             varchar,
  market_value_usd bigint,
  matches          integer,
  year             integer,
  goals            integer,
  assists          integer,
  yellow_cards     integer,
  red_cards        integer,
  id               bigint primary key
);
alter table public.player_market_values enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'player_market_values' and policyname = 'Public read-only') then
    create policy "Public read-only" on public.player_market_values for select to anon, authenticated using (true);
  end if;
end $$;
create index if not exists player_market_values_year_mv_idx on public.player_market_values (year, market_value_usd desc);
on conflict (id) do update set
  rank = excluded.rank,
  player_name = excluded.player_name,
  position = excluded.position,
  age = excluded.age,
  nationality = excluded.nationality,
  club = excluded.club,
  market_value_usd = excluded.market_value_usd,
  matches = excluded.matches,
  year = excluded.year,
  goals = excluded.goals,
  assists = excluded.assists,
  yellow_cards = excluded.yellow_cards,
  red_cards = excluded.red_cards;
